// RSA Encryption/Decryption Example using Web Crypto API
// This script demonstrates how to encrypt messages with public key and decrypt with private key
// Works with keys generated by web-os authentication system

/**
 * Import public key from base64 SPKI format
 * @param {string} publicKeyBase64 - Public key in base64 SPKI format
 * @returns {Promise<CryptoKey>} Imported public key
 */
async function importPublicKey(publicKeyBase64) {
  // Decode base64 to ArrayBuffer
  const binaryString = atob(publicKeyBase64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  
  // Import as SPKI format
  const publicKey = await crypto.subtle.importKey(
    'spki',
    bytes.buffer,
    {
      name: 'RSA-OAEP',
      hash: 'SHA-256'
    },
    false, // not extractable
    ['encrypt']
  );
  
  return publicKey;
}

/**
 * Import private key from base64 PKCS8 format
 * @param {string} privateKeyBase64 - Private key in base64 PKCS8 format
 * @returns {Promise<CryptoKey>} Imported private key
 */
async function importPrivateKey(privateKeyBase64) {
  // Decode base64 to ArrayBuffer
  const binaryString = atob(privateKeyBase64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  
  // Import as PKCS8 format
  const privateKey = await crypto.subtle.importKey(
    'pkcs8',
    bytes.buffer,
    {
      name: 'RSA-OAEP',
      hash: 'SHA-256'
    },
    false, // not extractable
    ['decrypt']
  );
  
  return privateKey;
}

/**
 * Encrypt message with public key
 * @param {string} message - Message to encrypt
 * @param {string} publicKeyBase64 - Public key in base64 SPKI format
 * @returns {Promise<string>} Encrypted message (base64)
 */
async function encryptMessage(message, publicKeyBase64) {
  const publicKey = await importPublicKey(publicKeyBase64);
  
  // Convert message to ArrayBuffer
  const encoder = new TextEncoder();
  const messageData = encoder.encode(message);
  
  // RSA-OAEP can only encrypt small amounts of data (max ~190 bytes for 2048-bit key)
  // For larger messages, we need to split or use hybrid encryption (RSA + AES)
  if (messageData.length > 190) {
    throw new Error('Message too long for RSA-OAEP. Maximum ~190 bytes. Use hybrid encryption for larger messages.');
  }
  
  // Encrypt
  const encrypted = await crypto.subtle.encrypt(
    {
      name: 'RSA-OAEP'
    },
    publicKey,
    messageData
  );
  
  // Convert to base64 for easy storage/transmission
  const encryptedArray = new Uint8Array(encrypted);
  const encryptedBase64 = btoa(String.fromCharCode(...encryptedArray));
  
  return encryptedBase64;
}

/**
 * Decrypt message with private key
 * @param {string} encryptedBase64 - Encrypted message (base64)
 * @param {string} privateKeyBase64 - Private key in base64 PKCS8 format
 * @returns {Promise<string>} Decrypted message
 */
async function decryptMessage(encryptedBase64, privateKeyBase64) {
  const privateKey = await importPrivateKey(privateKeyBase64);
  
  // Decode base64 to ArrayBuffer
  const binaryString = atob(encryptedBase64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  
  // Decrypt
  const decrypted = await crypto.subtle.decrypt(
    {
      name: 'RSA-OAEP'
    },
    privateKey,
    bytes.buffer
  );
  
  // Convert back to string
  const decoder = new TextDecoder();
  const message = decoder.decode(decrypted);
  
  return message;
}

/**
 * Example: Encrypt/Decrypt using keys from web-os account
 * Run this in browser console on web-os page after logging in
 */
async function exampleWithWebOSKeys() {
  console.log('%c🔐 RSA Encryption/Decryption Example', 'font-size: 18px; font-weight: bold; color: #4f7cff;');
  console.log('='.repeat(60));
  
  // Get account data
  const accountData = localStorage.getItem('webos.account.v1');
  if (!accountData) {
    console.error('❌ No account found. Please create an account first.');
    return;
  }
  
  const account = JSON.parse(accountData);
  const publicKeyBase64 = account.publicKey;
  
  if (!publicKeyBase64) {
    console.error('❌ No public key found in account.');
    return;
  }
  
  console.log('\n📦 Account Info:');
  console.log('Username:', account.username);
  console.log('Public Key (first 50 chars):', publicKeyBase64.substring(0, 50) + '...');
  
  // Get private key (requires password)
  const password = prompt('Enter your password to decrypt private key:');
  if (!password) {
    console.log('❌ Password required to decrypt private key.');
    return;
  }
  
  let privateKeyBase64;
  try {
    // Use web-os Auth API to get decrypted private key
    if (window.Auth) {
      privateKeyBase64 = await window.Auth.getPrivateKey(password);
      console.log('✅ Private key decrypted successfully');
    } else {
      console.error('❌ window.Auth not available. Make sure you are on web-os page.');
      return;
    }
  } catch (error) {
    console.error('❌ Failed to decrypt private key:', error.message);
    return;
  }
  
  // Example message
  const originalMessage = 'Hello, this is a secret message! 🔒';
  console.log('\n📝 Original Message:');
  console.log(originalMessage);
  
  try {
    // Encrypt with public key
    console.log('\n🔒 Encrypting with PUBLIC key...');
    const encrypted = await encryptMessage(originalMessage, publicKeyBase64);
    console.log('✅ Encrypted (base64):', encrypted);
    
    // Decrypt with private key
    console.log('\n🔓 Decrypting with PRIVATE key...');
    const decrypted = await decryptMessage(encrypted, privateKeyBase64);
    console.log('✅ Decrypted:', decrypted);
    
    // Verify
    if (decrypted === originalMessage) {
      console.log('\n✅ SUCCESS! Message encrypted and decrypted correctly.');
      console.log('\n💡 This proves:');
      console.log('  1. Public key can encrypt messages');
      console.log('  2. Only the matching private key can decrypt them');
      console.log('  3. Your key pair works correctly!');
    } else {
      console.error('\n❌ ERROR: Decrypted message does not match original!');
    }
    
  } catch (error) {
    console.error('\n❌ Error:', error.message);
    if (error.message.includes('too long')) {
      console.log('\n💡 Tip: RSA-OAEP can only encrypt small messages (~190 bytes).');
      console.log('   For larger messages, use hybrid encryption (RSA + AES).');
    }
  }
}

/**
 * Example: Encrypt message that someone else can send you
 * This simulates someone encrypting a message with YOUR public key
 */
async function exampleEncryptForMe(publicKeyBase64, message) {
  console.log('%c📨 Encrypting message for you...', 'font-size: 16px; font-weight: bold; color: #4f7cff;');
  
  try {
    const encrypted = await encryptMessage(message, publicKeyBase64);
    console.log('✅ Encrypted message:', encrypted);
    console.log('\n💡 Send this encrypted message to the owner of the private key.');
    console.log('   Only they can decrypt it!');
    return encrypted;
  } catch (error) {
    console.error('❌ Encryption failed:', error.message);
    throw error;
  }
}

/**
 * Example: Decrypt message encrypted with your public key
 */
async function exampleDecryptForMe(privateKeyBase64, encryptedBase64) {
  console.log('%c📬 Decrypting message for you...', 'font-size: 16px; font-weight: bold; color: #4f7cff;');
  
  try {
    const decrypted = await decryptMessage(encryptedBase64, privateKeyBase64);
    console.log('✅ Decrypted message:', decrypted);
    return decrypted;
  } catch (error) {
    console.error('❌ Decryption failed:', error.message);
    throw error;
  }
}

/**
 * Encrypt large message using hybrid encryption (RSA + AES)
 * RSA encrypts AES key, AES encrypts the message
 * @param {string} message - Message to encrypt (can be any size)
 * @param {string} publicKeyBase64 - Public key in base64 SPKI format
 * @returns {Promise<string>} Encrypted data (JSON string with encryptedKey and encryptedData)
 */
async function encryptLargeMessage(message, publicKeyBase64) {
  const encoder = new TextEncoder();
  const messageData = encoder.encode(message);
  
  // Generate random AES-GCM key
  const aesKey = await crypto.subtle.generateKey(
    {
      name: 'AES-GCM',
      length: 256
    },
    true, // extractable
    ['encrypt']
  );
  
  // Generate random IV (12 bytes for AES-GCM)
  const iv = crypto.getRandomValues(new Uint8Array(12));
  
  // Encrypt message with AES
  const encryptedData = await crypto.subtle.encrypt(
    {
      name: 'AES-GCM',
      iv: iv
    },
    aesKey,
    messageData
  );
  
  // Export AES key
  const exportedAesKey = await crypto.subtle.exportKey('raw', aesKey);
  
  // Encrypt AES key with RSA public key
  const publicKey = await importPublicKey(publicKeyBase64);
  const encryptedKey = await crypto.subtle.encrypt(
    {
      name: 'RSA-OAEP'
    },
    publicKey,
    exportedAesKey
  );
  
  // Convert to base64 for storage/transmission
  const encryptedKeyArray = new Uint8Array(encryptedKey);
  const encryptedKeyBase64 = btoa(String.fromCharCode(...encryptedKeyArray));
  
  const encryptedDataArray = new Uint8Array(encryptedData);
  const encryptedDataBase64 = btoa(String.fromCharCode(...encryptedDataArray));
  
  const ivArray = new Uint8Array(iv);
  const ivBase64 = btoa(String.fromCharCode(...ivArray));
  
  // Return as JSON string
  return JSON.stringify({
    encryptedKey: encryptedKeyBase64,
    encryptedData: encryptedDataBase64,
    iv: ivBase64
  });
}

/**
 * Decrypt large message encrypted with hybrid encryption (RSA + AES)
 * @param {string} encryptedJson - JSON string with encryptedKey, encryptedData, and iv
 * @param {string} privateKeyBase64 - Private key in base64 PKCS8 format
 * @returns {Promise<string>} Decrypted message
 */
async function decryptLargeMessage(encryptedJson, privateKeyBase64) {
  const decoder = new TextDecoder();
  const data = JSON.parse(encryptedJson);
  
  // Decode base64 strings
  const encryptedKeyBinary = atob(data.encryptedKey);
  const encryptedKeyBytes = new Uint8Array(encryptedKeyBinary.length);
  for (let i = 0; i < encryptedKeyBinary.length; i++) {
    encryptedKeyBytes[i] = encryptedKeyBinary.charCodeAt(i);
  }
  
  const encryptedDataBinary = atob(data.encryptedData);
  const encryptedDataBytes = new Uint8Array(encryptedDataBinary.length);
  for (let i = 0; i < encryptedDataBinary.length; i++) {
    encryptedDataBytes[i] = encryptedDataBinary.charCodeAt(i);
  }
  
  const ivBinary = atob(data.iv);
  const ivBytes = new Uint8Array(ivBinary.length);
  for (let i = 0; i < ivBinary.length; i++) {
    ivBytes[i] = ivBinary.charCodeAt(i);
  }
  
  // Decrypt AES key with RSA private key
  const privateKey = await importPrivateKey(privateKeyBase64);
  const decryptedKeyBuffer = await crypto.subtle.decrypt(
    {
      name: 'RSA-OAEP'
    },
    privateKey,
    encryptedKeyBytes.buffer
  );
  
  // Import decrypted AES key
  const aesKey = await crypto.subtle.importKey(
    'raw',
    decryptedKeyBuffer,
    {
      name: 'AES-GCM'
    },
    false,
    ['decrypt']
  );
  
  // Decrypt message with AES
  const decryptedData = await crypto.subtle.decrypt(
    {
      name: 'AES-GCM',
      iv: ivBytes
    },
    aesKey,
    encryptedDataBytes.buffer
  );
  
  // Convert back to string
  const message = decoder.decode(decryptedData);
  return message;
}

